EXTRA_POEMS = [{'id': '95c6417fd951bf350ab4', 'title': '山居秋暝', 'author': '王維', 'category': '唐诗', 'paragraphs': ['空山新雨後，天氣晚來秋。', '明月松間照，清泉石上流。', '竹喧歸浣女，蓮動下漁舟。', '隨意春芳歇，王孫自可留。'], 'featured': True}, {'id': '55d15a8a407dbfbb14e2', 'title': '靜夜思', 'author': '李白', 'category': '唐诗', 'paragraphs': ['床前明月光，疑是地上霜，', '舉頭望明月，低頭思故鄉。'], 'featured': True}, {'id': '444bcb23fd1d873d3cff', 'title': '春曉', 'author': '孟浩然', 'category': '唐诗', 'paragraphs': ['春眠不覺曉，處處聞啼鳥。', '夜來風雨聲，花落知多少。'], 'featured': True}, {'id': '8b21e87093ed074ae68f', 'title': '登鸛雀樓', 'author': '王之渙', 'category': '唐诗', 'paragraphs': ['白日依山盡，黃河入海流。', '欲窮千里目，更上一層樓。'], 'featured': True}, {'id': 'd65be89288f7b20e5776', 'title': '相思', 'author': '王維', 'category': '唐诗', 'paragraphs': ['紅豆生南國，春來發幾枝。', '願君多采擷，此物最相思。'], 'featured': True}, {'id': 'ed73a2d2cdcc5635c103', 'title': '鹿柴', 'author': '王維', 'category': '唐诗', 'paragraphs': ['空山不見人，但聞人語響。', '返景入深林，復照青苔上。'], 'featured': True}, {'id': '434f0fa141b63b0f4eca', 'title': '江雪', 'author': '柳宗元', 'category': '唐诗', 'paragraphs': ['千山鳥飛絕，萬徑人蹤滅。', '孤舟蓑笠翁，獨釣寒江雪。'], 'featured': True}, {'id': '2b4613e6ada23b42d641', 'title': '九月九日憶山東兄弟', 'author': '王維', 'category': '唐诗', 'paragraphs': ['獨在異鄉爲異客，每逢佳節倍思親。', '遙知兄弟登高處，遍插茱萸少一人。'], 'featured': True}, {'id': '7d410058ac73d7376959', 'title': '早發白帝城', 'author': '李白', 'category': '唐诗', 'paragraphs': ['朝辭白帝彩雲間，千里江陵一日還。', '兩岸猿聲啼不住，輕舟已過萬重山。'], 'featured': True}, {'id': '231106daa6ad1e436ee7', 'title': '遊子吟', 'author': '孟郊', 'category': '唐诗', 'paragraphs': ['慈母手中線，遊子身上衣。', '臨行密密縫，意恐遲遲歸。', '誰言寸草心，報得三春暉。'], 'featured': True}]
